clipA:
.keyframes-style-cube-Rotations {
  animation-name: keyframes-style-cube-Rotations;
  animation-duration: 5s;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
  animation-direction: alternate;
  animation-fill-mode: forwards;
}

@keyframes keyframes-style-cube-Rotations {
  0% {
    transform: rotateX(0deg) rotateY(0turn) rotateZ(0deg);
  }
  100% {
    transform: rotateX(var(--rotationX)) rotateY(1turn) rotateZ(360deg);
  }
}

